/* mobile islands: infinite ring carousel, arrows only, no bridges */
(function(){
  if(!matchMedia('(max-width:760px)').matches) return;
  var isles=document.querySelector('.isles'), svg=document.getElementById('islands'), caps=document.querySelector('.isles__caps');
  if(!isles||!svg||!caps||isles.classList.contains('m-ring')) return;
  var css=document.createElement('style');
  css.textContent=
    '.isles.m-ring{overflow:visible!important;margin-top:6px!important;margin-bottom:0!important;max-width:none!important;-webkit-mask-image:none!important;mask-image:none!important}'+
    '.isles.m-ring .islands{width:100%!important;max-width:none!important;margin:0!important;max-height:none!important;transform:none!important;display:block}'+
    '.isles.m-ring #bridges,.isles.m-ring #cour0,.isles.m-ring #cour1,.isles.m-ring #bridgeHits{display:none!important}'+
    '.isles__caps.m-ring{position:relative;display:block!important;box-sizing:border-box!important;max-width:none!important;margin-top:6px!important;margin-bottom:0!important;padding:0 calc(var(--rw,100vw)*.127 + 14px)!important;min-height:110px;text-align:center}'+
    '.isles__caps.m-ring .icap{display:none;opacity:1!important}'+
    '.isles__caps.m-ring .icap.m-on{display:block;animation:ringCap .45s ease}'+
    '@keyframes ringCap{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}'+
    '.isles__caps.m-ring .m-ring-a{position:absolute!important;z-index:3;top:calc(50% - max(16px,var(--rw,100vw)*.0425));margin:0!important;padding:0!important;width:max(32px,calc(var(--rw,100vw)*.085))!important;height:max(32px,calc(var(--rw,100vw)*.085))!important;min-width:0!important;border-radius:50%!important;display:grid!important;place-items:center}'+
    '.isles__caps.m-ring .m-ring-a svg{width:46%!important;height:46%!important;display:block}'+
    '.isles__caps.m-ring .m-ring-a--p{left:calc(var(--rw,100vw)*.05)!important;right:auto!important}.isles__caps.m-ring .m-ring-a--n{right:calc(var(--rw,100vw)*.05)!important;left:auto!important}'+
    '.m-dots{display:none!important}'+
    '.peek.m-ring-away{transform:translateY(calc(100% + 40px))!important;opacity:0!important;pointer-events:none!important}';
  document.head.appendChild(css);
  isles.classList.add('m-ring'); caps.classList.add('m-ring');

  // ---- slots, in viewBox units (1000 = screen width), measured from the reference
  var W=1000, RIM=320, CX=240, CY=330;           // island-local rim width, rim centre
  var SC=0.44*W/RIM, SS=0.28*W/RIM;               // centre 44% wide, sides 28% wide
  var groups=[0,1,2].map(function(i){ return svg.querySelector('.isl[data-isl="'+i+'"]'); });
  if(groups.some(function(g){return !g;})) return;
  var info=groups.map(function(g){
    var inner=g.querySelector('.isl-in'), w=document.createElementNS('http://www.w3.org/2000/svg','g');
    w.setAttribute('class','m-ring-w'); inner.parentNode.insertBefore(w,inner); w.appendChild(inner);
    var bb; try{ bb=inner.getBBox(); }catch(e){} if(!bb||!bb.width) bb={x:40,y:0,width:400,height:480};
    return {g:g,w:w,tx:+g.getAttribute('data-tx'),ty:+g.getAttribute('data-ty'),s:+g.getAttribute('data-s'),top:bb.y,bot:bb.y+bb.height};
  });
  var up=0, dn=0; info.forEach(function(o){ up=Math.max(up,(CY-o.top)*SC); dn=Math.max(dn,(o.bot-CY)*SC); });
  var YC=0, Y0=YC-up-30, H=up+dn+40;
  svg.setAttribute('viewBox','0 '+Y0.toFixed(1)+' '+W+' '+H.toFixed(1));
  svg.setAttribute('overflow','visible');
  // a true ring: islands sit 120deg apart on a circle seen from the front
  var R=0.31*W/Math.sin(2*Math.PI/3), SMIN=(SS-0.25*SC)/0.75, LIFT=0.085*W/0.75;
  function pose(th){ var c=Math.cos(th); return {x:0.5*W+R*Math.sin(th), y:YC-LIFT*(1-c)/2, s:SMIN+(SC-SMIN)*(1+c)/2, d:c}; }
  var SLOT={'-1':pose(-2*Math.PI/3),'0':pose(0),'1':pose(2*Math.PI/3)};
  var sky=svg.querySelector('.iqSky'); if(sky) sky.setAttribute('transform','translate(0 '+(Y0+8).toFixed(1)+') scale(.806) translate(0 30)');
  var cur=0, busy=false;
  function slotOf(i,c){ return ((i-c+4)%3)-1; }
  function place(o,x,y,S,op,d){
    var tx=(x-CX*S-o.tx)/o.s, ty=(y-CY*S-o.ty)/o.s, k=S/o.s;
    o.w.setAttribute('transform','translate('+tx.toFixed(2)+' '+ty.toFixed(2)+') scale('+k.toFixed(4)+')');
    o.w.style.opacity=op==null?'':op.toFixed(3); o._s=S; o._d=d==null?S:d;
  }
  function order(){   // paint back to front by depth; move a node only when the order really changes
    var want=info.slice().sort(function(a,b){return a._d-b._d;}), par=info[0].g.parentNode;
    for(var k=1;k<want.length;k++){ var a=want[k-1].g,b=want[k].g; if(!(a.compareDocumentPosition(b)&Node.DOCUMENT_POSITION_FOLLOWING)){ par.insertBefore(b,a.nextSibling); } }
  }
  function rest(){ info.forEach(function(o,i){ var s=SLOT[slotOf(i,cur)]; place(o,s.x,s.y,s.s,1,s.d); }); order(); }
  function ease(t){ return t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2; }
  var reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
  function go(dir){
    if(busy) return; busy=true;
    var from=info.map(function(o,i){return slotOf(i,cur);}); cur=(cur+dir+3)%3;
    var to=info.map(function(o,i){return slotOf(i,cur);});
    caps.querySelectorAll('.icap').forEach(function(c,k){ c.classList.toggle('m-on',k===cur); });
    if(reduce){ rest(); busy=false; return; }
    var t0=performance.now(), D=420;
    (function step(now){
      var t=Math.min(1,(now-t0)/D), e=0.5-0.5*Math.cos(Math.PI*t), sn=Math.sin(Math.PI*t), zx=1-0.5*sn, zs=1-0.1*sn;   // rotate the ring; mid-turn the circle tightens so the islands crowd together
      info.forEach(function(o,i){
        var th=(from[i]-dir*e)*2*Math.PI/3, p=pose(th);
        var x=500+(p.x-500)*zx, y=YC+(p.y-YC)*zs, S=p.s*zs;
        place(o,x,y,S,1,p.d);
      });
      order();
      if(t<1) requestAnimationFrame(step); else { rest(); busy=false; }
    })(t0);
  }
  function arrow(dir){
    var b=document.createElement('button'); b.type='button'; b.className='btn m-arrow m-ring-a m-ring-a--'+(dir<0?'p':'n');
    b.setAttribute('aria-label',dir<0?'Previous island':'Next island');
    b.innerHTML='<svg viewBox="0 0 16 16" aria-hidden="true"><path d="'+(dir<0?'M10 3L5 8l5 5':'M6 3l5 5-5 5')+'" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
    b.addEventListener('click',function(){ go(dir); }); caps.appendChild(b);
  }
  arrow(-1); arrow(1);
  // keep the caption block one fixed height so the arrows and the page below never jump
  function span(el){   // make el exactly as wide as the screen and centred on it
    el.style.marginLeft='0px'; el.style.marginRight='0px'; el.style.width='';
    var dw=document.documentElement.clientWidth, l=el.getBoundingClientRect().left;
    el.style.width=dw+'px'; el.style.marginLeft=(-l)+'px'; el.style.setProperty('--rw',dw+'px');
  }
  function fit(){
    span(isles); span(caps);
    var list=[].slice.call(caps.querySelectorAll('.icap')), h=0; caps.style.minHeight='0px';
    list.forEach(function(c){ list.forEach(function(x){ x.style.display=x===c?'block':'none'; }); h=Math.max(h,caps.offsetHeight); });
    list.forEach(function(x){ x.style.display=''; }); caps.style.minHeight=h+'px';
  }
  fit(); addEventListener('resize',fit); if(document.fonts&&document.fonts.ready) document.fonts.ready.then(fit);
  // the floating Watch-now card slides away only while it would sit on top of an arrow
  var peek=document.getElementById('peek'), arrows=[].slice.call(caps.querySelectorAll('.m-ring-a')), tick=false;
  function hit(a,b){ return !(a.right<b.left||a.left>b.right||a.bottom<b.top||a.top>b.bottom); }
  function guard(){ tick=false; if(!peek) return; if(!peek.offsetWidth) return; var cs=getComputedStyle(peek), r=innerWidth-(parseFloat(cs.right)||0), bt=innerHeight-(parseFloat(cs.bottom)||0); var p={left:r-peek.offsetWidth,right:r,top:bt-peek.offsetHeight,bottom:bt};
    var over=arrows.some(function(a){ return hit(a.getBoundingClientRect(),{left:p.left-8,right:p.right+8,top:p.top-8,bottom:p.bottom+8}); });
    peek.classList.toggle('m-ring-away',over); }
  addEventListener('scroll',function(){ if(!tick){ tick=true; requestAnimationFrame(guard); } },{passive:true}); guard();
  caps.querySelectorAll('.icap').forEach(function(c,k){ c.classList.toggle('m-on',k===cur); });
  rest();
})();

/* mobile first screen: static logos, and the "works with" row sits at the bottom of the first screen */
(function(){
  if(!matchMedia('(max-width:760px)').matches) return;
  var row=document.querySelector('.works__row'), art=document.querySelector('.hero__art'), hero=document.querySelector('.hero');
  if(!row||!art||!hero) return;
  var css=document.createElement('style');
  css.textContent=
    '.works__row.m-mq{animation:none!important;transform:none!important;width:100%!important;max-width:none!important;flex-wrap:nowrap!important;justify-content:center!important;gap:0 16px!important;margin:0!important}'+
    '.works__row.m-mq>:nth-child(n+5){display:none!important}'+
    '.works__row.m-mq .prov--logo svg{height:12.5px!important;width:auto}.works .eyebrow{font-size:10.5px!important;letter-spacing:.14em!important}'+
    '.sea .works{padding-top:26px!important;gap:10px!important}'+
    '.hero__copy{gap:18px!important}';
  document.head.appendChild(css);
  var works=document.querySelector('.sea .works');
  function setW(w){ art.style.setProperty('width',w.toFixed(1)+'px','important'); art.style.setProperty('max-width','none','important'); }
  function over(){ var vh=(window.visualViewport&&visualViewport.height)||innerHeight; return row.getBoundingClientRect().bottom+scrollY-(vh-34); }
  function fit(){
    hero.style.removeProperty('padding-top'); var cq=hero.querySelector('.hero__copy'); if(cq) cq.style.removeProperty('gap'); if(works) works.style.removeProperty('padding-top');
    // 1) size the ship (200..300) so the logo row lands at the bottom of the first screen
    for(var k=0;k<3;k++){ var r=art.getBoundingClientRect(), d=over(); if(Math.abs(d)<2) break;
      setW(Math.max(200,Math.min(320,r.width-d*(r.width/(r.height||r.width))))); }
    var d=over(); if(d<=1) return;
    // 2) short screens: tighten the space above the sea, then the space above the logos, then the ship again
    var pt0=parseFloat(getComputedStyle(hero).paddingTop)||0, cut=Math.min(d,Math.max(0,pt0-8)); hero.style.setProperty('padding-top',(pt0-cut)+'px','important'); d=over(); if(d<=1) return;
    var cp=hero.querySelector('.hero__copy'); if(cp){ cp.style.setProperty('gap','12px','important'); d=over(); if(d<=1) return; }
    if(works){ var pt=parseFloat(getComputedStyle(works).paddingTop)||0, c2=Math.min(d,Math.max(0,pt-22)); works.style.setProperty('padding-top',(pt-c2)+'px','important'); d=over(); if(d<=1) return; }
    for(var j=0;j<3;j++){ var q=art.getBoundingClientRect(); d=over(); if(d<=1) break; setW(Math.max(150,q.width-d*(q.width/(q.height||q.width)))); }
  }
  // the Watch-now card stays out of the way while it would cover the logo row
  var peek=document.getElementById('peek'), tk=false;
  function guard(){ tk=false; if(!peek||!peek.offsetWidth) return; var cs=getComputedStyle(peek), bt=innerHeight-(parseFloat(cs.bottom)||0), top=bt-peek.offsetHeight, w=(works||row).getBoundingClientRect();
    var hit=w.bottom>top-6 && w.top<bt; peek.classList.toggle('m-fold-away',hit); }
  var gcss=document.createElement('style'); gcss.textContent='.peek.m-fold-away{transform:translateY(calc(100% + 40px))!important;opacity:0!important;pointer-events:none!important}'; document.head.appendChild(gcss);
  addEventListener('scroll',function(){ if(!tk){ tk=true; requestAnimationFrame(guard); } },{passive:true}); setTimeout(guard,50); setTimeout(guard,1500);
  if(scrollY<5){ fit(); if(document.fonts&&document.fonts.ready) document.fonts.ready.then(fit); setTimeout(fit,600); }
  var lw=innerWidth; addEventListener('resize',function(){ if(innerWidth!==lw){ lw=innerWidth; fit(); } });
})();
